PAGES_BASE = getattr(getattr(orca, "pages", None), "PagesPluginCapabilityBase", None)

if PAGES_BASE is not None:
    class PipSpoolPageCapability(PAGES_BASE):
        def __init__(self):
            super().__init__()
            LIFECYCLE_COORDINATOR.register_page(self)

        def on_unload(self):
            LIFECYCLE_COORDINATOR.unregister_page(self)

        def get_name(self):
            return "PipSpool"

        def get_ui(self):
            return pipspool_page_html(
                pipspool_page_state(friendly_initial_error=True)
            )

        def get_icon(self):
            try:
                if (
                    not PAGE_ICON_PATH.exists()
                    or PAGE_ICON_PATH.read_text(encoding="utf-8")
                    != PIPSPOOL_PAGE_ICON_SVG
                ):
                    PAGE_ICON_PATH.parent.mkdir(parents=True, exist_ok=True)
                    PAGE_ICON_PATH.write_text(
                        PIPSPOOL_PAGE_ICON_SVG, encoding="utf-8"
                    )
                return str(PAGE_ICON_PATH)
            except Exception as exc:
                log(f"[PAGE ICON ERROR] {exc}")
                return ""

        def _post_state(self, message_type="state", notice=None):
            payload = pipspool_page_state(notice)
            payload["type"] = message_type
            self.post_message(payload)

        def _post_initial_state(self):
            self._post_state()

        def _refresh_from_lifecycle(self):
            # Called by the coordinator's debounce worker, never directly from
            # Orca's lifecycle callback. post_message marshals delivery to UI.
            self._post_state()

        def _background(self, operation):
            def work():
                try:
                    notice = operation()
                    self._post_state("sync-result", notice)
                except Exception as exc:
                    log(f"[PAGE ERROR] {exc}")
                    self.post_message({"type": "error", "message": str(exc)})
            if not start_background_thread(
                threading.Thread(target=work, daemon=True),
                "PipSpool page action",
            ):
                self.post_message({
                    "type": "error",
                    "message": THREAD_PERMISSION_RETRY_MESSAGE,
                })

        def on_message(self, message):
            if not isinstance(message, dict):
                return
            action = message.get("action")
            if action in ("ready", "refresh", "check-theme-season"):
                for payload in theme_transfer_messages(theme_state()):
                    self.post_message(payload)
            if action == "ready":
                self._post_initial_state()
            elif action == "set-theme":
                try:
                    for payload in theme_transfer_messages(save_theme(message.get("theme"))):
                        self.post_message(payload)
                except (OSError, ValueError) as exc:
                    self.post_message({"type": "error", "message": str(exc)})
            elif action == "feedback":
                try:
                    if not webbrowser.open_new_tab(FEEDBACK_URL):
                        log("[FEEDBACK] The system browser did not accept the GitHub Issues URL.")
                except Exception as exc:
                    log(f"[FEEDBACK ERROR] {exc}")
            elif action == "open-spool":
                try:
                    spool_id = int(message.get("spool_id"))
                    if spool_id <= 0:
                        raise ValueError("Spool ID must be positive")
                    spoolman_url = normalize_url(
                        load_settings().get("spoolman_url", DEFAULT_SPOOLMAN_URL)
                    )
                    target = f"{spoolman_url}/?sel=spool:{spool_id}"
                    if not webbrowser.open_new_tab(target):
                        log(
                            "[OPEN SPOOL] The system browser did not accept "
                            f"the Spoolman URL for spool #{spool_id}."
                        )
                except (TypeError, ValueError) as exc:
                    log(f"[OPEN SPOOL ERROR] Invalid spool ID: {exc}")
                except Exception as exc:
                    log(f"[OPEN SPOOL ERROR] {exc}")
            elif action == "refresh":
                self._post_state()
            elif action == "save-fields":
                selected, _remove = parse_field_config({"selected_fields": message.get("selected_fields", [])})
                live_preset_values = host_filament_preset_snapshot(selected)
                def save_fields():
                    created, populated = save_advanced_field_selection(
                        selected, live_preset_values
                    )
                    detail = (
                        f" Filled Orca values for {populated} Spoolman filament(s)."
                        if populated else " All existing values were already populated."
                    )
                    return (
                        f"Saved {len(selected)} selected advanced field(s). "
                        f"Created {created} field(s)." + detail
                    )
                self._background(save_fields)
            elif action == "save-columns":
                columns = message.get("spool_table_columns")
                if not isinstance(columns, list):
                    columns = []
                selected_columns = [
                    column for column in SPOOL_TABLE_COLUMNS if column in columns
                ]
                save_settings({"spool_table_columns": selected_columns})
            elif action == "save-spool-id-gcode":
                enabled = message.get("enabled") is True
                save_settings({"inject_spool_id_gcode": enabled})
                notice = (
                    "Active spool G-code enabled. Synchronize to update filament profiles."
                    if enabled else
                    "Active spool G-code disabled. Synchronize to remove PipSpool's managed command."
                )
                self._post_state("state", notice)
            elif action in ("sync", "sync-spool"):
                selected, _remove = parse_field_config({"selected_fields": message.get("selected_fields", [])})
                live_preset_values = host_filament_preset_snapshot(selected)
                target_spool_id = message.get("spool_id") if action == "sync-spool" else None
                if action == "sync-spool" and (isinstance(target_spool_id, bool) or not isinstance(target_spool_id, int) or target_spool_id <= 0):
                    self.post_message({"type": "error", "message": "Invalid spool ID"})
                    return
                def synchronize():
                    report, _spools = sync_with_spoolman(
                        selected, live_preset_values=live_preset_values,
                        spool_id=target_spool_id,
                    )
                    suffix = " Restart OrcaSlicer to load changed presets." if report.restart_required else ""
                    return ("Synchronization completed with errors. Review Last synchronization." if report.errors else "Synchronization completed.") + suffix
                self._background(synchronize)
            elif action == "cleanup":
                def cleanup():
                    selected, _remove = parse_field_config({"selected_fields": message.get("selected_fields", [])})
                    save_settings({"selected_fields": list(selected)})
                    settings = load_settings()
                    removed = SpoolmanClient(settings["spoolman_url"]).remove_unselected_orca_filament_fields(selected)
                    return f"Removed {removed} unselected PipSpool field(s)."
                self._background(cleanup)


def settings_window_state() -> dict[str, Any]:
    settings = load_settings()
    lifecycle = LIFECYCLE_COORDINATOR.diagnostics()
    return {
        "type": "settings-state",
        "profile_name_template": profile_name_template(settings),
        "spool_id_command_template": spool_id_command_template(settings),
        "spoolman_url": settings.get("spoolman_url", DEFAULT_SPOOLMAN_URL),
        "show_pipspool_page": settings.get("show_pipspool_page", True) is not False,
        "low_stock_threshold_grams": low_stock_threshold(settings),
        "lifecycle_supported": lifecycle["supported"],
        "lifecycle_mode": lifecycle["mode"],
    }


class SettingsCapability(orca.script.ScriptPluginCapabilityBase):
    def get_name(self):
        return "PipSpool Settings"

    def _restore_host_settings(self) -> bool:
        """Restore user settings from Orca's supported capability config."""
        getter = getattr(self, "get_config", None)
        if not callable(getter):
            return False
        try:
            stored = getter()
            stored = json.loads(stored) if isinstance(stored, str) else stored
            if not isinstance(stored, dict):
                return False
            restored: dict[str, Any] = {}
            if "spool_id_command_template" in stored:
                restored["spool_id_command_template"] = spool_id_command_template(stored)
            if "profile_name_template" in stored:
                restored["profile_name_template"] = profile_name_template(stored)
            if "spoolman_url" in stored:
                restored["spoolman_url"] = normalize_url(stored["spoolman_url"])
            if isinstance(stored.get("show_pipspool_page"), bool):
                restored["show_pipspool_page"] = stored["show_pipspool_page"]
            threshold = numeric(stored.get("low_stock_threshold_grams"))
            if threshold is not None and threshold >= 0:
                restored["low_stock_threshold_grams"] = round(threshold, 1)
            if not restored:
                return False
            HOST_USER_SETTINGS.clear()
            HOST_USER_SETTINGS.update(restored)
            try:
                save_settings(restored)
            except OSError as exc:
                # The host configuration remains available even if a Linux
                # installation cannot update PipSpool's legacy shared file.
                log(f"[SETTINGS FILE MIRROR] {exc}")
            return "spoolman_url" in restored
        except (OSError, TypeError, ValueError, json.JSONDecodeError) as exc:
            log(f"[HOST SETTINGS LOAD] {exc}")
            return False

    def _save_host_settings(self, update: dict[str, Any]) -> bool:
        """Persist user settings through Orca and refresh the runtime cache."""
        saver = getattr(self, "save_config", None)
        if not callable(saver):
            return False
        current = load_settings()
        host_settings = {
            key: current[key]
            for key in HOST_CONFIG_KEYS
            if key in current
        }
        host_settings.update({key: update[key] for key in HOST_CONFIG_KEYS if key in update})
        try:
            if not saver(json.dumps(host_settings, separators=(",", ":"))):
                return False
        except Exception as exc:
            log(f"[HOST SETTINGS SAVE] {exc}")
            return False
        HOST_USER_SETTINGS.clear()
        HOST_USER_SETTINGS.update(host_settings)
        return True

    def on_load(self):
        restored = self._restore_host_settings()
        if not restored and has_saved_settings():
            # Migrate existing PipSpool installations into Orca's durable
            # capability configuration without making the user re-enter data.
            self._save_host_settings(load_settings())
        elif not restored:
            self._open_settings_window()

    def execute(self):
        self._open_settings_window()
        return orca.ExecutionResult.success("PipSpool settings opened")

    def _open_settings_window(self):
        self._restore_host_settings()
        current_settings = load_settings()
        current_url = current_settings.get("spoolman_url", DEFAULT_SPOOLMAN_URL)
        show_page = current_settings.get("show_pipspool_page", True) is not False
        current_low_stock_threshold = low_stock_threshold(current_settings)
        safe_current_url = escape(str(current_url), quote=True)
        safe_default_url = escape(DEFAULT_SPOOLMAN_URL, quote=True)
        safe_name_template = escape(profile_name_template(current_settings), quote=True)
        safe_spool_command = escape(spool_id_command_template(current_settings), quote=True)
        show_page_checked = " checked" if show_page else ""
        safe_low_stock_threshold = escape(f"{current_low_stock_threshold:g}", quote=True)
        html = f"""<!doctype html>
<html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>
:root {{ color-scheme:dark; --page:#202124; --panel:#292a2d; --field:#1f2022;
  --line:#55585d; --text:#f1f3f4; --muted:#aeb4ba; --accent:#37c9da;
  --accent-hover:#51d6e5; }}
* {{ box-sizing:border-box; }}
body {{ margin:0; padding:28px; background:var(--page); color:var(--text);
  font:14px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif; }}
.header {{ display:flex; align-items:center; gap:16px; margin-bottom:20px; }}
.logo {{ width:64px; height:64px; flex:0 0 64px; object-fit:contain;
  filter:drop-shadow(0 4px 8px rgba(0,0,0,.28)); }}
h1 {{ margin:0; font-size:21px; line-height:1.15; }}
.subtitle {{ margin:4px 0 0; color:var(--muted); font-size:13px; }}
.card {{ padding:20px; border:1px solid #3d3f43; border-radius:12px; background:var(--panel); }}
.sync-card,.display-card {{ margin-top:12px; }}
.card-title {{ margin:0 0 5px; font-size:15px; font-weight:650; }}
.help {{ margin:0 0 17px; color:var(--muted); }}
label {{ display:block; margin-bottom:7px; font-weight:600; }}
input {{ width:100%; padding:11px 12px; border:1px solid var(--line); border-radius:7px;
  outline:none; background:var(--field); color:var(--text); font:inherit; }}
input:focus {{ border-color:var(--accent); box-shadow:0 0 0 2px rgba(55,201,218,.18); }}
.toggle {{ display:flex; align-items:flex-start; gap:11px; margin:13px 0 0; font-weight:400; cursor:pointer; }}
.toggle input {{ width:18px; height:18px; margin:2px 0 0; flex:0 0 18px; accent-color:var(--accent); }}
.toggle-copy {{ display:block; }}
.toggle-title {{ display:block; font-weight:650; }}
.toggle-help {{ display:block; margin-top:3px; color:var(--muted); font-size:12px; font-weight:400; }}
.example {{ margin-top:7px; color:var(--muted); font-size:12px; }}
.actions {{ display:flex; align-items:center; justify-content:space-between; gap:10px; margin-top:22px; }}
.right {{ display:flex; gap:9px; }}
button {{ min-height:36px; padding:8px 14px; border:1px solid var(--line); border-radius:7px;
  cursor:pointer; background:transparent; color:var(--text); font:600 13px system-ui,sans-serif; }}
button:hover {{ background:rgba(255,255,255,.06); }}
.primary {{ border-color:var(--accent); background:var(--accent); color:#102326; }}
.primary:hover {{ background:var(--accent-hover); }}
</style></head><body>
<div class="header"><img class="logo" src="{PIPSPOOL_LOGO_DATA_URI}" alt="PipSpool logo"><div><h1>PipSpool settings</h1>
<p class="subtitle">Connect OrcaSlicer to your Spoolman server</p></div></div>
<div class="card"><p class="card-title">Spoolman connection</p>
<p class="help">Enter the address you normally use to open Spoolman.</p>
<label for="url">Server address</label>
<input id="url" type="url" spellcheck="false" autocomplete="off"
 value="{safe_current_url}" placeholder="{safe_default_url}">
<div class="example">Include http:// or https:// and the port, if one is used.</div></div>
<div class="card display-card"><p class="card-title">Profile naming</p>
<label for="profileNameTemplate">Name format</label>
<input id="profileNameTemplate" value="{safe_name_template}" maxlength="120" spellcheck="false">
<div class="example">Reorder {{spool_id}}, {{material}}, {{name}} and {{vendor}}. {{spool_id}} is required exactly once and includes (#42). The suffix “ - PipSpool” is always added.</div>
<div id="namePreview" class="example"></div>
<button type="button" id="resetNameTemplate">Reset to default</button>
<div class="example">Saving does not rename profiles. Synchronize to apply; restart OrcaSlicer after profiles are renamed. Full synchronization applies the format to all active spools.</div></div>
<div class="card display-card"><p class="card-title">Active spool G-code</p>
<label for="spoolIdCommand">Spool-ID command</label>
<input id="spoolIdCommand" value="{safe_spool_command}" maxlength="200" spellcheck="false">
<div class="example">Use {{spool_id}} exactly once. Default: SET_ACTIVE_SPOOL ID={{spool_id}}. Example alternative: M555 S={{spool_id}}.</div>
<div id="spoolCommandPreview" class="example"></div>
<details class="example" style="margin:12px 0"><summary style="cursor:pointer;font-weight:650">Printer / firmware command examples</summary>
<p>The command depends on the installed firmware and macros, rather than the printer brand alone.</p>
<dl style="margin:10px 0;line-height:1.65">
<dt style="font-weight:650">Klipper + Moonraker + Spoolman</dt>
<dd style="margin:2px 0 14px"><code>SET_ACTIVE_SPOOL ID={{spool_id}}</code><br>Default. Requires the SET_ACTIVE_SPOOL macro from Moonraker's Spoolman setup. Spool #42 produces <code>SET_ACTIVE_SPOOL ID=42</code>.</dd>
<dt style="font-weight:650">Anycubic GoKlipper with an M555 Spoolman bridge</dt>
<dd style="margin:2px 0 14px"><code>M555 S={{spool_id}}</code><br>Example reported for issue #16. Use only when your installed firmware or custom macro implements this command. Spool #42 produces <code>M555 S=42</code>; this is not a universal Anycubic command.</dd>
<dt style="font-weight:650">Klipper with a custom SET_SPOOL_ID macro</dt>
<dd style="margin:2px 0 14px"><code>SET_SPOOL_ID ID={{spool_id}}</code><br>Use only if you have defined this exact macro and its ID parameter. It is not Moonraker's documented default.</dd>
<dt style="font-weight:650">Happy Hare / MMU managing the active spool</dt>
<dd style="margin:2px 0 14px">Turn <b>Active spool G-code</b> off on the dashboard if your configured MMU integration already selects the correct active Spoolman spool on tool changes.</dd>
<dt style="font-weight:650">Printer without a compatible Spoolman command</dt>
<dd style="margin:2px 0 0">Turn <b>Active spool G-code</b> off. PipSpool still synchronizes profiles; use your printer's own filament-selection workflow.</dd>
</dl></details>
<button type="button" id="resetSpoolCommand">Reset command to default</button>
<div class="example">The dashboard Active spool G-code switch turns managed spool-ID output off entirely. Unrelated Start G-code stays intact. Per-spool Spoolman start_gcode overrides this command and also accepts {{spool_id}}. Synchronize after saving, then restart OrcaSlicer when prompted.</div></div>
<div class="card sync-card"><p class="card-title">Filament setting ownership</p>
<p class="help">Orca supplies the initial values selected from its filament-setting tabs.
Blank Spoolman fields inherit from Orca; populated fields are preserved as overrides.</p>
<div class="example">Use “Reset Spoolman Filament Settings from Orca” only when you
want to replace all PipSpool-managed overrides for active filaments.</div></div>
<div class="card sync-card"><p class="card-title">Network permissions</p>
<p class="help">OrcaSlicer manages approval for the configured Spoolman server.
After approving a request, repeat the action if Orca refused the current attempt.</p>
<div class="example">If approved prompts return after restarting OrcaSlicer, use
an Orca build containing permission fix #16658 (commit 6626377). The original
2.5.0 Alpha predates this fix. A different host may require its own approval.</div></div>
<div class="card sync-card"><p class="card-title">Orca change detection</p>
<p class="help">New Orca builds notify PipSpool when filament presets are saved.
Older Orca versions continue to use PipSpool's compatibility checks.</p>
<div id="lifecycleStatus" class="example">Checking Orca lifecycle support…</div></div>
<div class="card display-card"><p class="card-title">PipSpool page</p>
<p class="help">Choose whether PipSpool adds its dashboard to OrcaSlicer's top navigation.</p>
<label class="toggle" for="showPage"><input id="showPage" type="checkbox"{show_page_checked}>
<span class="toggle-copy"><span class="toggle-title">Show PipSpool page in OrcaSlicer</span>
<span class="toggle-help">Synchronization and plugin actions keep working when the page is hidden. Restart OrcaSlicer after changing this setting.</span></span></label></div>
<div class="card display-card"><p class="card-title">Low filament warning</p>
<p class="help">Highlight loaded gate/toolhead tiles when their remaining filament reaches this amount.</p>
<label for="lowStockThreshold">Warning threshold (grams)</label>
<input id="lowStockThreshold" type="number" min="0" step="1" value="{safe_low_stock_threshold}">
<div class="example">The default is 100 g. Set the threshold to 0 to disable low-stock warnings.</div></div>
<div class="actions"><button onclick="send('test')">Test connection</button>
<div class="right"><button onclick="send('cancel')">Cancel</button>
<button class="primary" onclick="send('save')">Save settings</button></div></div>
<script>
var spoolCommand = document.getElementById('spoolIdCommand');
function previewSpoolCommand() {{
  document.getElementById('spoolCommandPreview').textContent='Example for spool #42: '+spoolCommand.value.split('{{spool_id}}').join('42');
}}
spoolCommand.oninput=previewSpoolCommand;
document.getElementById('resetSpoolCommand').onclick=function(){{spoolCommand.value={json.dumps(DEFAULT_SPOOL_ID_COMMAND)};previewSpoolCommand();}};
previewSpoolCommand();
var nameTemplate = document.getElementById('profileNameTemplate');
function previewName() {{
  var values={{spool_id:'(#42)',material:'PETG',name:'Galaxy Black',vendor:'Prusament'}};
  var text=nameTemplate.value.replace(/\\{{([^{{}}]+)\\}}/g,function(all,key){{return Object.prototype.hasOwnProperty.call(values,key)?values[key]:all;}});
  document.getElementById('namePreview').textContent='Example: '+text.replace(/\\s+/g,' ').trim()+' - PipSpool';
}}
nameTemplate.oninput=previewName;
document.getElementById('resetNameTemplate').onclick=function(){{nameTemplate.value={json.dumps(DEFAULT_PROFILE_NAME_TEMPLATE)};previewName();}};
previewName();
var url = document.getElementById('url');
var showPage = document.getElementById('showPage');
var lowStockThreshold = document.getElementById('lowStockThreshold');
var lifecycleStatus = document.getElementById('lifecycleStatus');
function settingsPayload(action) {{
  return {{action:action,spool_id_command_template:spoolCommand.value,profile_name_template:nameTemplate.value,url:url.value,show_pipspool_page:showPage.checked,low_stock_threshold_grams:lowStockThreshold.value}};
}}
function send(action) {{
  if(window.orca&&typeof window.orca.postMessage==='function')window.orca.postMessage(settingsPayload(action));
  else lifecycleStatus.textContent='Settings bridge is not available in this Orca build.';
}}
function applySettingsState(data) {{
  if(!data||data.type!=='settings-state')return;
  spoolCommand.value=data.spool_id_command_template||{json.dumps(DEFAULT_SPOOL_ID_COMMAND)};previewSpoolCommand();
  nameTemplate.value=data.profile_name_template||{json.dumps(DEFAULT_PROFILE_NAME_TEMPLATE)};previewName();
  url.value=data.spoolman_url||{json.dumps(DEFAULT_SPOOLMAN_URL)};
  showPage.checked=data.show_pipspool_page!==false;
  lowStockThreshold.value=data.low_stock_threshold_grams==null?{DEFAULT_LOW_STOCK_THRESHOLD_GRAMS}:data.low_stock_threshold_grams;
  lifecycleStatus.textContent=data.lifecycle_supported===true
    ?'Lifecycle events enabled — saved Orca filament presets trigger a debounced status check.'
    :'Compatibility mode — use Refresh after changing Orca or Spoolman.';
}}
function startSettingsBridge(attempt) {{
  attempt=attempt||0;
  if(window.orca&&typeof window.orca.postMessage==='function'&&typeof window.orca.onMessage==='function'){{
    window.orca.onMessage(applySettingsState);
    window.orca.postMessage({{action:'load-settings'}});
    return;
  }}
  if(attempt<100)window.setTimeout(function(){{startSettingsBridge(attempt+1);}},100);
  else lifecycleStatus.textContent='Settings bridge is not available in this Orca build.';
}}
url.addEventListener('keydown', function(event) {{ if (event.key === 'Enter') send('save'); }});
document.addEventListener('DOMContentLoaded', function() {{ startSettingsBridge(0); }});
</script>
</body></html>"""

        def on_message(data):
            if not isinstance(data, dict):
                return
            action = data.get("action")
            if action == "load-settings":
                post = getattr(window, "post", None)
                if callable(post):
                    post(settings_window_state())
                return
            if action == "cancel":
                window.close()
                return
            if action == "test":
                try:
                    test_url = normalize_url(data.get("url", ""))
                except Exception as exc:
                    show_message(str(exc), title="Connection test", icon="error")
                    return

                def test_connection():
                    try:
                        spools = SpoolmanClient(test_url).active_spools()
                        show_message(
                            f"Connection successful.\n\nSpoolman returned {len(spools)} active spool(s).",
                            title="Connection test",
                        )
                    except Exception as exc:
                        log(f"[CONNECTION TEST ERROR] {exc}")
                        show_message(
                            f"Could not connect to Spoolman.\n\n{exc}",
                            title="Connection test",
                            icon="error",
                        )

                if not start_background_thread(
                    threading.Thread(target=test_connection, daemon=True),
                    "Spoolman connection test",
                ):
                    show_message(
                        THREAD_PERMISSION_RETRY_MESSAGE,
                        title="Connection test",
                        icon="error",
                    )
                return
            if action == "save":
                try:
                    updated_show_page = bool(data.get("show_pipspool_page", True))
                    saved_show_page = (
                        load_settings().get("show_pipspool_page", True) is not False
                    )
                    visibility_changed = saved_show_page != updated_show_page
                    updated_low_stock_threshold = numeric(
                        data.get("low_stock_threshold_grams")
                    )
                    if updated_low_stock_threshold is None or updated_low_stock_threshold < 0:
                        raise ValueError("Low-stock warning threshold must be 0 grams or more")
                    updated_name_template = validate_profile_name_template(data.get("profile_name_template", profile_name_template()))
                    naming_changed = updated_name_template != profile_name_template()
                    updated_spool_command = validate_spool_id_command_template(data.get("spool_id_command_template", spool_id_command_template()))
                    spool_command_changed = updated_spool_command != spool_id_command_template()
                    settings_update = {
                        "spool_id_command_template": updated_spool_command,
                        "profile_name_template": updated_name_template,
                        "spoolman_url": normalize_url(data.get("url", "")),
                        "show_pipspool_page": updated_show_page,
                        "low_stock_threshold_grams": round(updated_low_stock_threshold, 1),
                    }
                    host_saved = self._save_host_settings(settings_update)
                    file_saved = False
                    try:
                        save_settings(settings_update)
                        file_saved = True
                    except OSError as exc:
                        log(f"[SETTINGS FILE SAVE] {exc}")
                    if not host_saved and not file_saved:
                        raise RuntimeError("OrcaSlicer could not save PipSpool settings")
                    window.close()
                    message = "PipSpool settings saved."
                    if spool_command_changed:
                        message += "\n\nSynchronize to apply the spool-ID command. Restart OrcaSlicer after profiles change."
                    if naming_changed:
                        message += "\n\nSynchronize to apply profile naming. Restart OrcaSlicer after profiles are renamed."
                    if visibility_changed:
                        message += "\n\nRestart OrcaSlicer to apply the page visibility change."
                    show_message(message)
                except Exception as exc:
                    show_message(str(exc), icon="error")

        window = orca.host.ui.create_window(
            html=html,
            title="PipSpool Settings",
            on_message=on_message,
        )


@orca.plugin
class PipSpoolPlugin(orca.base):
    def register_capabilities(self):
        if PAGES_BASE is not None and pipspool_page_enabled():
            orca.register_capability(PipSpoolPageCapability)
        orca.register_capability(SyncCapability)
        orca.register_capability(ResetFilamentSettingsCapability)
        orca.register_capability(LegacyCleanupCapability)
        orca.register_capability(SettingsCapability)
